expectedWireMessages = [(name, [(field, fromIntegral number) | (_, _, field, number, _) <- fields]) | (name, _, fields) <- wireMessages]

expectedWireSchema :: Text
expectedWireSchema = Text.unlines $
  ["syntax = \"proto2\";", "package pulsar.proto;", "option java_package = \"org.apache.pulsar.common.api.proto\";", "option optimize_for = LITE_RUNTIME;", ""]
  <> concatMap renderEnum wireEnums <> concatMap renderMessage wireMessages
 where
  renderEnum (name, values) = ["enum " <> name <> " {"]
    <> ["  " <> key <> " = " <> Text.pack (show value) <> ";" | (key, value) <- values]
    <> ["}", ""]
  renderMessage (name, enums, fields) = ["message " <> name <> " {"]
    <> concatMap (map ("  " <>) . renderEnum) enums
    <> map renderField fields <> ["}", ""]
  renderField (label, kind, name, number, defaultValue) = "  " <> label <> " " <> kind <> " " <> name <> " = "
    <> Text.pack (show number) <> maybe "" (\value -> " [default = " <> value <> "]") defaultValue <> ";"
